document.addEventListener('pointermove',event=>{if(dragging||modal||catalogSlide!==null)return;const node=event.target.closest?.('[data-block]');if(node&&node.parentElement.id==='manuscript'){if(activeBlock!==node.dataset.block||document.getElementById('hover-tools').hidden)showHover(node.dataset.block)}else if(!event.target.closest?.('#hover-tools')){if(!document.getElementById('hover-tools').contains(document.activeElement))document.getElementById('hover-tools').hidden=true}});
function groupFor(p,id,scope){let start=p.blocks.findIndex(b=>b.id===id);if(start<0)return null;let end=start+1;if(scope==='section'){while(start>0&&!/^h[1-6]$/.test(p.blocks[start].tag))start--;if(!/^h[1-6]$/.test(p.blocks[start].tag))start=0;end=start+1;while(end<p.blocks.length&&!/^h[1-6]$/.test(p.blocks[end].tag))end++}return {start,end}}
function moveContent(delta,forcedScope){if(current().view!=='article'){toast('This snapshot is read-only. Open Working words to edit your local copy.');return}commitTyping();const p=current(),scope=forcedScope||moveScope,id=activeBlock||selected?.anchor,g=groupFor(p,id,scope);if(!g)return;let destination;if(scope==='section'){if(delta<0){if(g.start===0)return;destination=g.start-1;while(destination>0&&!/^h[1-6]$/.test(p.blocks[destination].tag))destination--}else{if(g.end===p.blocks.length)return;destination=g.end+1;while(destination<p.blocks.length&&!/^h[1-6]$/.test(p.blocks[destination].tag))destination++}}else destination=delta<0?g.start-1:g.end+1;if(destination<0||destination>p.blocks.length)return;keyboardBlock=id;reorder(p,g,destination,'Move '+(scope==='section'?'section':'content'));save();render();toast('Moved locally. Quote identity, notes and photo captions stay attached.')}
function reorder(p,g,destination,label){snapshot(label);const moved=p.blocks.splice(g.start,g.end-g.start);const index=destination>g.start?destination-moved.length:destination;p.blocks.splice(index,0,...moved);p.rev++}
function startPointerDrag(event){if(current().view!=='article')return;if(event.button!==0)return;event.preventDefault();event.stopPropagation();commitTyping();const p=current(),id=activeBlock,scope=moveScope,g=groupFor(p,id,scope);if(!g)return;const x0=event.clientX,y0=event.clientY,pointerId=event.pointerId,button=event.currentTarget;let moved=false;button.setPointerCapture?.(pointerId);const move=ev=>{if(ev.pointerId!==pointerId)return;if(!moved&&Math.hypot(ev.clientX-x0,ev.clientY-y0)<5)return;if(!moved){moved=true;dragging={id,scope,g};window.getSelection()?.removeAllRanges();document.querySelector(`[data-block="${id}"]`)?.classList.add('dragSource');document.body.classList.add('contentDragging')}ev.preventDefault();let target=document.elementFromPoint(ev.clientX,ev.clientY)?.closest('[data-block]');if(!target){const list=[...document.querySelectorAll('#manuscript>[data-block]')];target=list.reduce((best,item)=>{const r=item.getBoundingClientRect(),distance=Math.min(Math.abs(ev.clientY-r.top),Math.abs(ev.clientY-r.bottom));return !best||distance<best.distance?{item,distance}:best},null)?.item}if(target){const r=target.getBoundingClientRect(),after=ev.clientY>r.top+r.height/2;dropTarget={id:target.dataset.block,after};let line=document.querySelector('.insertionLine');if(!line){line=document.createElement('div');line.className='insertionLine';document.body.append(line)}line.style.left=r.left+'px';line.style.width=r.width+'px';line.style.top=(after?r.bottom:r.top)+'px'}const ws=document.getElementById('workspace');if(ev.clientY<120)ws.scrollTop-=12;else if(ev.clientY>innerHeight-55)ws.scrollTop+=12};const finish=ev=>{if(ev.pointerId!==pointerId)return;document.removeEventListener('pointermove',move);document.removeEventListener('pointerup',finish);document.removeEventListener('pointercancel',cancel);button.releasePointerCapture?.(pointerId);let changed=false;if(moved&&dropTarget){const destination=p.blocks.findIndex(b=>b.id===dropTarget.id)+(dropTarget.after?1:0);if(destination<g.start||destination>g.end){keyboardBlock=id;reorder(p,g,destination,'Drag '+scope);save();changed=true}}endDrag();document.body.classList.remove('contentDragging');if(changed){render();toast('Content placed locally. Undo restores its previous position.')}else document.querySelector('.dragSource')?.classList.remove('dragSource')};const cancel=ev=>{if(ev.pointerId!==pointerId)return;document.removeEventListener('pointermove',move);document.removeEventListener('pointerup',finish);document.removeEventListener('pointercancel',cancel);endDrag();document.body.classList.remove('contentDragging')};document.addEventListener('pointermove',move,{passive:false});document.addEventListener('pointerup',finish);document.addEventListener('pointercancel',cancel)}
function beginDrag(event){if(current().view!=='article')return;commitTyping();const p=current(),scope=moveScope,g=groupFor(p,activeBlock,scope);if(!g)return;dragging={id:activeBlock,scope,g};event.dataTransfer.setData('text/x-magazine-study',activeBlock);event.dataTransfer.effectAllowed='move';document.querySelector(`[data-block="${activeBlock}"]`)?.classList.add('dragSource')}
function dragOver(event){if(!dragging)return;event.preventDefault();event.dataTransfer.dropEffect='move';const block=event.target.closest('[data-block]');if(!block)return;const rect=block.getBoundingClientRect(),after=event.clientY>rect.top+rect.height/2;dropTarget={id:block.dataset.block,after};let line=document.querySelector('.insertionLine');if(!line){line=document.createElement('div');line.className='insertionLine';document.body.append(line)}line.style.left=rect.left+'px';line.style.width=rect.width+'px';line.style.top=(after?rect.bottom:rect.top)+'px'}
function dropContent(event){if(!dragging||!dropTarget)return;event.preventDefault();const p=current(),i=p.blocks.findIndex(b=>b.id===dropTarget.id),destination=i+(dropTarget.after?1:0);if(destination<dragging.g.start||destination>dragging.g.end){reorder(p,dragging.g,destination,'Drag '+dragging.scope);save()}endDrag();render()}
function endDrag(){dragging=null;dropTarget=null;document.querySelector('.insertionLine')?.remove();document.querySelectorAll('.dragSource').forEach(el=>el.classList.remove('dragSource'))}document.addEventListener('dragend',endDrag);
document.addEventListener('keydown',event=>{if(current().view==='article'&&event.altKey&&(event.key==='ArrowUp'||event.key==='ArrowDown')){event.preventDefault();activeBlock=activeBlock||keyboardBlock||selected?.anchor;moveContent(event.key==='ArrowUp'?-1:1,event.shiftKey?'section':'block')}if(event.key==='Escape'){modal=null;catalogSlide=null;mobileProjects=false;hideHover();render()}});
function modalHTML(p){let body='';if(modal==='instruction')body=`<h2>Discuss these words.</h2><div class="small">Sample interaction · no live AI</div><label>Selected phrase</label><div class="context">${esc(selected?.text||'')}</div><label>Instruction</label><textarea id="instruction" rows="3" placeholder="Keep my meaning, but simplify this sentence…">Keep my meaning; make these words clearer.</textarea><details style="margin-top:14px;font-size:10px;color:#929a84"><summary>Surrounding paragraph used as context</summary><div class="context" style="margin-top:8px">${esc(targetSignature(p,selected?.anchor))}</div></details><div class="actions"><button class="primary" onclick="prepareNote()">Prepare sample discussion</button><button onclick="modal=null;render()">Cancel</button></div>`;if(modal==='quote')body=`<h2>Keep the speaker’s words.</h2><div class="context">${esc(selected?.text||'')}</div><p>This quotation retains its source identity when moved. The sample does not rewrite it. Human edits remain possible in this local copy, but real integration must retain original evidence and run the quote check.</p><div class="actions"><button onclick="modal=null;render()">Return to document</button></div>`;if(modal==='history')body=`<h2>Local changes</h2><div class="historyList">${p.history.map((h,i)=>`<button onclick="restoreHistory(${i})">${esc(h.label)}<span class="small">Before local r${h.rev} · restore content and notes</span></button>`).join('')||'<p>No local changes yet.</p>'}</div>`;if(modal==='noteContext')body=`<h2>Target and nearby words</h2><p>Stable passage identity follows a move. A changed target or nearby context requires refinement before Accept. Quote originals and photo captions travel with their content.</p><div class="context">${esc(p.note?.target||'')}</div><label>Captured surrounding context</label><div class="context">${esc(p.note?.context||'')}</div><p class="small">No model, command, file writeback or approval occurs.</p>`;if(modal==='about')body=`<h2>One focused document study.</h2><p>This code-only checkout uses configured source catalogs or clearly synthetic fixtures. The existing 58 + 8 portrait renderers are retained; photographs and private records are not bundled.</p><p>Handles appear on hover/focus. Drag a passage or photo; choose Whole section to move its heading and contents. Keyboard: Alt+↑/↓; Shift also moves its section.</p><p>Source quotations, photo/caption identity and notes remain attached. Native selection can span paragraphs; this sample AI acceptance is deliberately limited to a phrase within one passage.</p><p>Suggestions are deterministic samples, explicitly not generated by a live model. Actual physical records, statuses, approvals and the older mock’s storage remain untouched.</p>`;return `<div class="popoverBackdrop" onclick="if(event.target===this){modal=null;render()}"><section class="popover"><button class="close quiet" onclick="modal=null;render()">Close ×</button>${body}</section></div>`}
function restoreHistory(index){if(current().view==='record'){toast('Open Working words to restore local editing history.');return}const p=current(),h=p.history[index];if(!h)return;commitTyping();const before={label:'Before restoring local history',blocks:copy(p.blocks),note:copy(p.note),slides:copy(p.slides),caption:p.caption,rev:p.rev};p.blocks=copy(h.blocks);p.note=copy(h.note);p.slides=copy(h.slides);p.caption=h.caption;p.history.unshift(before);p.rev++;modal=null;selected=null;save();render();toast('Local history restored; original files unchanged.')}
function carousel(p){return `<section class="carouselWork"><div class="carouselIntro"><div><h2>The whole word sequence.</h2><p>Configured carousel words · review is independent from layout approval. Templates are prototype visual choices, not approved layouts. No Hong Kong photos are attached; photo slots remain honest.</p></div><button onclick="modal='carouselSource';render()">Source / what changed</button></div><div class="carouselSequence">${p.slides.map((s,i)=>`<article class="carouselItem"><div class="slideMeta"><span class="role">${i+1} · ${esc(s.role)}${s.credit?' · '+esc(s.credit):''}</span><span><button aria-label="Move slide ${i+1} up" onclick="moveSlide(${i},-1)">↑</button><button aria-label="Move slide ${i+1} down" onclick="moveSlide(${i},1)">↓</button></span></div><div class="donorFrame" data-slide="${i}"><div class="donorScale">${renderSlide(s)}</div></div><div class="slideFooter"><span>${esc(IG.T[s.template]?.name||s.template)} · 1080 × 1350</span><button onclick="openCatalog(${i})">Layout / photo / crop</button></div></article>`).join('')}</div><section class="caption"><span class="small">CAPTION · EDITABLE LOCAL COPY</span><div class="words" contenteditable="true" role="textbox" aria-label="Carousel caption" onblur="carouselSession=null" oninput="editCarouselCaption(this.innerText)">${esc(p.caption)}</div></section></section>`}
function beginCarouselEdit(key,label){const session=current().id+':'+key;if(carouselSession!==session){snapshot(label);carouselSession=session}}
function refreshSavedCue(){const el=document.querySelector('.saved');if(el)el.textContent='Saved locally · r'+current().rev}
function editCarouselCaption(text){beginCarouselEdit('caption','Before editing carousel caption');current().caption=text;current().carouselRev=(current().carouselRev||1)+1;current().rev++;save();refreshSavedCue()}

function renderSlide(s){return IG.render(s.template||'M12',{role:s.role,text:s.text,credit:s.credit,label:current().title||current().name,photos:s.photos||[]},{logo:''})}
function wireCarousel(){document.querySelectorAll('.donorFrame[data-slide]').forEach(frame=>{const i=Number(frame.dataset.slide),s=current().slides[i],entry=IG.T[s.template];const parts=s.text.split(/\n\s*\n/),expected=entry?.textParts?Array.from({length:entry.textParts},(_,n)=>n===entry.textParts-1?parts.slice(n).join('\n\n'):parts[n]||''):[s.template==='H10'?s.text.split(/\s+·\s+/)[0]:s.text];const nodes=[...frame.querySelectorAll('.donorScale div,.donorScale span')];expected.forEach((text,part)=>{const match=nodes.find(n=>n.children.length===0&&n.textContent===text);if(match){match.contentEditable='true';match.dataset.studyText=part;match.setAttribute('role','textbox');match.setAttribute('aria-label','Slide '+(i+1)+' words'+(expected.length>1?' part '+(part+1):''));match.onblur=()=>{carouselSession=null};match.oninput=event=>{event.stopPropagation();beginCarouselEdit('slide-'+i,'Before editing carousel slide words');if(s.template==='H10'){const close=s.text.split(/\s+·\s+/);close[0]=match.innerText;s.text=close.join(' · ')}else if(entry?.textParts>1){const vals=expected.slice();frame.querySelectorAll('[data-study-text]').forEach(n=>vals[Number(n.dataset.studyText)]=n.innerText);s.text=vals.join('\n\n')}else s.text=match.innerText;current().carouselRev=(current().carouselRev||1)+1;current().rev++;save();refreshSavedCue()}}});});scaleAll()}
function scaleAll(){document.querySelectorAll('.donorFrame').forEach(frame=>{const scale=frame.querySelector('.donorScale');if(scale)scale.style.transform='scale('+frame.getBoundingClientRect().width/1080+')'})}window.addEventListener('resize',()=>{scaleAll();positionMargin();positionOriginalNotes();positionHover()});
function openCatalog(i){catalogSlide=i;catalogQuery='';catalogGroup='all';catalogLimit=12;modal=null;render()}function catalogHTML(p){const s=p.slides[catalogSlide],entries=Object.entries(IG.T),groups=[...new Set(entries.map(([id,t])=>t.group||'Earlier Magazine templates'))],list=entries.filter(([id,t])=>(catalogGroup==='all'||(t.group||'Earlier Magazine templates')===catalogGroup)&&(!catalogQuery||(t.name+' '+id+' '+(t.group||'')).toLowerCase().includes(catalogQuery.toLowerCase())));return `<aside class="catalogDrawer"><button class="close quiet" onclick="catalogSlide=null;render()">Close ×</button><h2>Slide ${catalogSlide+1}</h2><p class="small">Exact existing 58 original canvases + 8 earlier Magazine renderers. Changing a layout is a local prototype choice; the original word review remains pending.</p><input aria-label="Search templates" placeholder="Search all 66 templates…" value="${esc(catalogQuery)}" oninput="catalogQuery=this.value;catalogLimit=12;renderCatalogOnly()"><select aria-label="Template group" onchange="catalogGroup=this.value;catalogLimit=12;renderCatalogOnly()"><option value="all">All groups · 66</option>${groups.map(g=>`<option ${catalogGroup===g?'selected':''}>${esc(g)}</option>`).join('')}</select><div class="templateGrid">${list.slice(0,catalogLimit).map(([id,t])=>`<button class="templateOption" onclick="chooseTemplate('${id}')"><div class="donorFrame"><div class="donorScale">${IG.render(id,{role:s.role,text:s.text,credit:s.credit,label:current().title||current().name,photos:s.photos||[]},{logo:''})}</div></div><span class="name">${esc(t.name)} · ${t.photos} photo slot${t.photos===1?'':'s'}</span></button>`).join('')}</div>${list.length>catalogLimit?`<button style="width:100%" onclick="catalogLimit+=12;renderCatalogOnly()">Show more · ${list.length-catalogLimit} remaining</button>`:''}<h3>Photo slots</h3><p class="small">Hong Kong assets are not loaded. No Porcelain photograph is substituted into this story.</p>${Array.from({length:IG.T[s.template]?.photos||0},(_,slot)=>`<div class="small">Slot ${slot+1} · no matched story photo</div><div class="cropInputs"><div><label>Crop X · percent</label><input type="number" min="0" max="100" value="${s.photos?.[slot]?.x??50}" aria-label="Photo ${slot+1} crop X" onchange="setCrop(${slot},'x',this.value)"></div><div><label>Crop Y · percent</label><input type="number" min="0" max="100" value="${s.photos?.[slot]?.y??50}" aria-label="Photo ${slot+1} crop Y" onchange="setCrop(${slot},'y',this.value)"></div></div>`).join('')}<details style="margin-top:18px;font-size:10px;color:#8e967d"><summary>Template provenance</summary><p>${esc(IG.T[s.template]?.sourceFile||'ig-templates.js · measured 1080×1350 canvas')}<br>${esc(IG.T[s.template]?.originalId||s.template)}</p></details></aside>`}
function renderCatalogOnly(){const existing=document.querySelector('.catalogDrawer');if(!existing)return;const focused=existing.querySelector('input[aria-label="Search templates"]'),caret=focused?.selectionStart,hadFocus=document.activeElement===focused;existing.outerHTML=catalogHTML(current());scaleAll();if(hadFocus){const next=document.querySelector('input[aria-label="Search templates"]');next.focus();next.setSelectionRange(caret,caret)}}function chooseTemplate(id){commitTyping();snapshot('Before changing local slide layout');const s=current().slides[catalogSlide];s.template=id;current().carouselRev=(current().carouselRev||1)+1;current().rev++;save();render();toast('Exact donor layout selected locally. Words are preserved; no approval or export.')}
function setCrop(slot,axis,value){snapshot('Before changing carousel crop intent');const s=current().slides[catalogSlide];if(!s.photos)s.photos=[];if(!s.photos[slot])s.photos[slot]={src:'',x:50,y:50};s.photos[slot][axis]=Math.max(0,Math.min(100,Number(value)||0));current().rev++;save();refreshSavedCue();toast('Crop focus saved locally. An actual Hong Kong photo still needs to be matched.')}
function moveSlide(index,delta){if(current().view!=='carousel')return;const p=current(),to=index+delta;if(to<0||to>=p.slides.length)return;commitTyping();snapshot('Before moving a carousel slide');const [slide]=p.slides.splice(index,1);p.slides.splice(to,0,slide);p.rev++;save();render();toast('Slide order changed only in this local copy.')}


const STEP_SHORT=['In','Source','Research','Pick','Draft','Read','Checked','Photos','Placed','Look','Feedback','Confirmed'];
const ORIGINAL_STEPS=['Dropped in','Source','Research and map','Your pick','Draft','Your read','Your changes in, checked','Photos in the folder','Photos placed','Your look, then publish','Feedback sent','Confirmed'];
function initializeWorkflow(){for(const p of state.projects){const data=WORKFLOW_RECORDS[p.id];if(!data)continue;if(!p.positions)p.positions={words:p.scroll||0};if(!p.recordsLinked){if(p.referenceOnly||!p.blocks.length){const blocks=[],notes=[];for(const [part,record] of data.words.entries()){if(data.words.length>1)blocks.push({id:'boundary-'+p.id+'-'+part,tag:'h2',html:esc(record.title),source:'Record boundary · '+record.path,quote:false});const offset=blocks.length,newBlocks=blockModels(record.html,'record-'+p.id+'-'+part);newBlocks.forEach(b=>b.source=record.path);blocks.push(...newBlocks);record.notes.forEach(n=>notes.push({...n,anchor:newBlocks[n.anchorIndex]?.id||newBlocks[newBlocks.length-1]?.id,path:record.path}))}p.blocks=blocks;p.originalNotes=notes;p.scroll=0;p.positions.words=0;p.title=data.words[0]?.title||p.name;p.subtitle='Current working words · local copy of the retained DEV record.';p.referenceOnly=false;p.view='article';p.rev=Math.max(1,p.rev||1)}else if(!p.originalNotes){const record=data.words[0],sourceBlocks=blockModels(record?.html||'','source-map');p.originalNotes=(record?.notes||[]).map(n=>{const source=sourceBlocks[n.anchorIndex];const target=p.blocks.find(b=>source&&plain(b.html)===plain(source.html));return {...n,anchor:target?.id||p.blocks[Math.min(n.anchorIndex,p.blocks.length-1)]?.id,path:record.path}})}p.recordsLinked=true;p.viewedStage=6;if(p.id==='hk')p.outputMode='words'}p.blocks.forEach(b=>{const text=plain(b.html).trim();if((/^['\"“]/.test(text)&&/['\"”]$/.test(text))&&b.source!=='Human writing · local study')b.quote=true});if(!p.viewedStage)p.viewedStage=6;if(p.id==='hk'&&!p.outputMode)p.outputMode='words'}save()}
function viewKey(p){return p.view==='record'?'stage-'+p.viewedStage:p.view==='carousel'?'output-'+(p.outputMode||'words'):'words'}
function currentProcessStep(p){if(p.id==='porcelain')return 11;if(/^Your read/.test(p.step||''))return 6;return null}
function recordEvidence(p,n){const data=WORKFLOW_RECORDS[p.id];return !!data?.stages[String(n)]?.length||(n===8&&p.id==='porcelain')||(n===11&&p.id==='porcelain')||(n===6&&!data&&p.blocks.some(b=>plain(b.html).trim()))}
function workflowBar(p){const actual=currentProcessStep(p);return `<nav class="workflowNavigation" aria-label="Original twelve-step workflow"><div class="workflowLegend"><span>Current: <strong>${esc(p.step||p.status)}</strong>${p.id==='hk'&&p.slides?.length?' · independent carousel words':''}</span><span>${p.view==='record'?'Viewing: '+(typeof p.viewedStage==='number'?p.viewedStage+'. '+ORIGINAL_STEPS[p.viewedStage-1]:'current carousel words snapshot'):'Current local working copy'}</span></div><div class="workflowSteps">${ORIGINAL_STEPS.map((name,i)=>{const n=i+1,viewed=p.view==='record'&&p.viewedStage===n,has=recordEvidence(p,n);return `<button class="workflowStep ${actual===n?'isCurrent':''} ${viewed?'isViewed':''}" aria-label="View step ${n}: ${name} (read-only)${actual===n?', current author work':''}${has?', retained record available':''}" ${viewed?'aria-current="step"':''} title="${name} · ${has?'retained record available, not a completion claim':'snapshot connection gap'}" onclick="viewPhase(${n})"><span class="stepNumber">${n}</span><span class="stepName">${STEP_SHORT[i]}</span>${has?'<i class="recordDot" aria-hidden="true"></i>':''}${actual===n?'<span class="currentMark">current</span>':''}</button>`}).join('')}</div></nav>`}
function readonlyHTML(html){const root=document.createElement('div');root.innerHTML=html;root.querySelectorAll('[contenteditable]').forEach(el=>el.removeAttribute('contenteditable'));root.querySelectorAll('[data-block]').forEach(el=>el.removeAttribute('data-block'));root.querySelectorAll('[role="textbox"]').forEach(el=>{el.removeAttribute('role');el.removeAttribute('aria-multiline')});return root.innerHTML}
function historicalNotice(p,stage){const data=WORKFLOW_RECORDS[p.id],later=!!data?.words.length&&((typeof stage==='number'&&stage<6)||(p.id==='porcelain'&&typeof stage==='number'&&stage<11)),records=data?.stages[String(stage)]||[];return `<div class="historicalToolbar"><span>${later?'Earlier version · read-only · current manuscript available':'Read-only snapshot · working copy kept separate'}</span>${records.length>1?`<select aria-label="Jump to retained record" onchange="if(this.value)document.getElementById(this.value)?.scrollIntoView({behavior:'smooth',block:'start'})"><option value="">Records (${records.length})</option>${records.map((r,i)=>`<option value="phase-record-${i}">${esc(shortRecordName(r.name))}</option>`).join('')}</select>`:''}<button title="Open the editable browser-local study copy; never the published article" onclick="setView('article')">Open the draft</button></div>`}
function compactRecordPage(record,index,stage){const dom=document.createElement('div');dom.innerHTML=readonlyHTML(record.html);const provenance=[];for(const child of [...dom.children]){if(child.tagName==='P'&&/^Based on:/i.test(child.textContent.trim())){provenance.push(child.outerHTML);child.remove()}}if(!dom.querySelector('h1')){const title=document.createElement('h1');title.textContent=record.title||record.name;dom.prepend(title)}const caveats=[record.legacy?'Retained earlier AI analysis; reconcile older claims and naming with the corrected source and current DEV. This view does not rerun or endorse it.':'Existing working record, read-only snapshot.',record.setAside?'This exploration was explicitly set aside; it is not a decision to repeat.':'',stage===9||stage===10?'Same current DEV shown for composition/look, not a distinct historical placement or publication receipt.':''].filter(Boolean);return `<article class="recordPage compactRecord" id="phase-record-${index}"><details class="recordDetails"><summary>Details</summary><div><p>${esc(record.path)}</p>${record.date?`<p>Date: ${esc(record.date)}</p>`:''}${caveats.map(text=>`<p>${esc(text)}</p>`).join('')}${provenance.join('')}${originalRecordLink(record.path)}</div></details><div class="recordBody">${dom.innerHTML}</div>${record.notes.length?`<aside class="recordAnnotations"><h3>Retained editorial annotations</h3>${record.notes.map(n=>`<p><strong>${esc(n.kind)}</strong> ${esc(n.text)}</p>`).join('')}</aside>`:''}</article>`}
function viewCurrentWork(){const p=current(),actual=currentProcessStep(p);if(actual){viewPhase(actual);return}if(p.id==='hk'){rememberPosition();p.view='record';p.viewedStage='carousel-words';p.scroll=p.positions?.['stage-carousel-words']||0;activeBlock=null;keyboardBlock=null;selected=null;catalogSlide=null;modal=null;save();render()}}
function retainedCarouselSnapshot(projectId){return projectId==='hk'&&typeof HK_LINEUP!=='undefined'?copy(HK_LINEUP):null}
function readonlyCarouselPhase(p){return `<section class="phaseReader"><article class="recordPage"><h2>Current carousel words — read-only</h2><div class="recordBody">${HK_LINEUP.slides.map((s,i)=>`<h3>${i+1}. ${esc(s.role)}${s.credit?' · '+esc(s.credit):''}</h3><p>${esc(s.text)}</p>`).join('')}<h3>Caption</h3><p>${esc(HK_LINEUP.caption)}</p></div><footer>Original artifact snapshot. No word approval or look/export action occurs.</footer></article><button onclick="setOutputMode('words')">Carousel working words · local copy</button></section>`}
function viewPhase(stage){rememberPosition();const p=current();delete p.readSource;p.viewedStage=stage;p.phaseScroll=0;p.view='record';activeBlock=null;keyboardBlock=null;selected=null;window.getSelection()?.removeAllRanges();p.scroll=p.positions?.[viewKey(p)]||0;catalogSlide=null;modal=null;selected=null;save();render()}
function setOutputMode(mode){rememberPosition();const p=current();delete p.readSource;p.view='carousel';p.outputMode=mode;p.scroll=p.positions?.[viewKey(p)]||0;catalogSlide=null;modal=null;selected=null;save();render()}
function browserWordsReader(p){return `<article class="recordPage"><span class="small">Browser writing · read-only</span><h2>${esc(p.title||p.name)}</h2><div class="recordBody">${readonlyHTML(p.blocks.map(blockHTML).join(''))}</div><p class="small">These words are retained in this browser. The working file and original stay separate.</p></article>`}
function phaseReader(p){const data=WORKFLOW_RECORDS[p.id]||{stages:{},words:[]},stage=p.viewedStage,records=data.stages[String(stage)]||[];let html='';if(stage===6&&p.readSource==='browser'){return `<section class="phaseReader">${browserWordsSignature(p)?browserWordsReader(p):'<article class="recordPage"><p>This browser writing changed. Reopen Pieces to choose its current owner.</p></article>'}</section>`}if(stage==='carousel-words'){return readonlyCarouselPhase(p)}if(records.length){html=records.map((record,i)=>compactRecordPage(record,i,stage)).join('')}
else if(stage===6&&!WORKFLOW_RECORDS[p.id]){html=browserWordsReader(p)}else if(stage===8&&p.id==='porcelain'){html=`<article class="recordPage"><h2>Photos in the project</h2><p>Real retained public story assets, available alongside text work. Viewing this collection does not start placement or block writing.</p><div class="stagePhotoGrid">${p.blocks.filter(b=>b.tag==='figure').map(b=>readonlyHTML(b.html)).join('')}</div></article>`}
else if(stage===11){html=`<article class="recordPage"><h2>Feedback</h2><p>No delivery or feedback receipt is configured for this output. Nothing is sent or confirmed here.</p></article>`}
else{html=`<article class="recordPage"><h2>${ORIGINAL_STEPS[stage-1]}</h2><p>The connected snapshot has no appropriate record displayed for this phase. That is a view-connection gap, not evidence that AI work did not happen or a request to repeat it.</p>${stage===1&&data.stages['2'].length?'<p>This legacy story has an existing source transcript. An invented RAW or original recording is not substituted.</p>':''}${stage===12?'<p>Confirmation is not inferred from publication or saved outputs. Only the recorded feedback/correction outcome can establish it.</p>':''}<button onclick="viewPhase(6)">Read the current working words</button></article>`}
if(stage===4&&data.words.some(r=>r.plan)){html=`<article class="recordPage recordedDirection"><h2>What this piece became</h2>${data.words.filter(r=>r.plan).map(r=>`<p>${esc(r.plan)}</p><div class="small">${esc(r.path)}</div>`).join('')}</article>`+html}return `<section class="phaseReader">${html}</section>`}
function shortRecordName(name){return name.replace(/^(SRC|DEV|GUIDE|RESEARCH|BRIEF|MAP|PLANS|CONTEXT|CHECK|NOTES) - /,'').slice(0,58)}
function originalNotesHTML(p){if(!p.originalNotes?.length)return '';return `<div class="originalNotes" id="originalNotes"><div class="sourceNotesLabel">Existing editorial notes · record snapshot</div>${p.originalNotes.map((n,i)=>`<article class="originalNote" data-note-anchor="${n.anchor}" data-note-index="${i}"><strong>${esc(n.kind)}</strong><p>${esc(n.text)}</p><button onclick="jumpSourceNote('${n.anchor}')">At this passage ↗</button><span>${esc(n.path?.split('/').pop()||'DEV annotation')}</span></article>`).join('')}</div>`}
function jumpSourceNote(id){const target=document.querySelector(`[data-block="${id}"]`);target?.scrollIntoView({behavior:'smooth',block:'center'});marginOpen=true;refreshDiscussion()}
function positionOriginalNotes(){const list=document.getElementById('originalNotes'),margin=document.getElementById('margin');if(!list||!margin)return;let previous=0;const base=margin.getBoundingClientRect().top;list.querySelectorAll('[data-note-anchor]').forEach(note=>{const target=document.querySelector(`[data-block="${note.dataset.noteAnchor}"]`);let top=target?target.getBoundingClientRect().top-base:previous+15;top=Math.max(top,previous+15);if(innerWidth>850){note.style.position='absolute';note.style.top=top+'px';previous=top+note.getBoundingClientRect().height}else{note.style.position='static';note.style.marginTop='12px'}})}
function carouselWords(p){return `<section class="wordSequence"><header><span class="small">CAROUSEL WORDS · BROWSER COPY</span><h2>The words, in swipe order.</h2><p>Read and edit the whole sequence here; layout is separate.</p><button onclick="setOutputMode('look')">Inspect portrait Look</button><button class="quiet" onclick="modal='carouselSource';render()">What changed</button></header>${p.slides.map((slide,i)=>`<article class="wordSlide"><div class="wordRole"><span>${i+1} · ${esc(slide.role)}${slide.credit?' · '+esc(slide.credit):''}</span><div><button aria-label="Move slide ${i+1} up" onclick="moveSlide(${i},-1)">↑</button><button aria-label="Move slide ${i+1} down" onclick="moveSlide(${i},1)">↓</button></div></div><div class="slideProse" contenteditable="true" role="textbox" aria-label="Slide ${i+1} words" onblur="carouselSession=null" oninput="editWordLine(${i},this.innerText)">${esc(slide.text)}</div></article>`).join('')}<section class="caption"><span class="small">CAPTION · LOCAL EDITING COPY</span><div class="words" contenteditable="true" role="textbox" aria-label="Carousel caption" onblur="carouselSession=null" oninput="editCarouselCaption(this.innerText)">${esc(p.caption)}</div></section><footer>No words-yes, look approval, export or publication is recorded by this study.</footer></section>`}
function editWordLine(index,text){beginCarouselEdit('words-'+index,'Before editing carousel words');current().slides[index].text=text;current().carouselRev=(current().carouselRev||1)+1;current().rev++;save();refreshSavedCue()}

const EXISTING_PROJECTS=[];
function initializeBrowser(){if(!state.theme)state.theme='dark';if(!state.projectFilter)state.projectFilter='all';state.projects.forEach(p=>{if(!p.folder)p.folder=p.id==='notes'?'Ideas':'Projects';if(!p.step)p.step=p.id==='porcelain'?'Feedback':p.id==='hk'?'Carousel words':'Writing'});for(const entry of EXISTING_PROJECTS){if(!state.projects.some(p=>p.id===entry.id))state.projects.push({...entry,referenceOnly:true,status:entry.step,view:'reference',blocks:[],slides:[],history:[],rev:0,note:null,scroll:0,folder:'Projects'})}save()}
function applyTheme(){const dark=state.theme==='dark'||state.theme==='system'&&window.matchMedia('(prefers-color-scheme: dark)').matches;document.documentElement.dataset.theme=dark?'dark':'light'}
const systemTheme=window.matchMedia('(prefers-color-scheme: dark)');systemTheme.addEventListener?.('change',()=>{if(state.theme==='system')applyTheme()});
function projectBrowser(p){const folders=[...new Set(state.projects.map(q=>q.folder||'Projects'))],list=state.projects.filter(q=>state.projectFilter==='all'||state.projectFilter==='archive'?state.projectFilter==='all'||q.archived:state.projectFilter==='active'?!q.archived:!q.archived&&q.folder===state.projectFilter);return `<aside class="rail ${mobileProjects?'open':''}"><div class="brand">Content creation</div><div class="railHeader"><span>Projects</span><div><button aria-label="New project" title="New project" onclick="modal='newProject';render()">＋</button><button aria-label="File or organize project" title="File or organize current project" onclick="modal='filing';render()">⋯</button></div></div><select class="projectFilter" aria-label="Project list" onchange="state.projectFilter=this.value;save();render()"><option value="all" ${state.projectFilter==='all'?'selected':''}>All projects</option><option value="active" ${state.projectFilter==='active'?'selected':''}>Active</option>${folders.map(f=>`<option ${state.projectFilter===f?'selected':''}>${esc(f)}</option>`).join('')}<option value="archive" ${state.projectFilter==='archive'?'selected':''}>Archive</option></select>${list.map(q=>`<button class="project ${q.id===p.id?'on':''}" onclick="switchProject('${q.id}')" title="${esc(q.name)}"><strong>${esc(q.name)}</strong><span class="small">${esc(q.step||q.status)}</span></button>`).join('')}<div class="railfooter">Local document study.<br>Configured projects; browser-only filing.</div></aside>`}
function originalURL(record){const base=window.AR_CREATE_PACKAGE_CONFIG?.originalReaderBaseUrl;return base?new URL('read/'+record.split('/').map(encodeURIComponent).join('/'),base.endsWith('/')?base:base+'/').href:'#original-reader-unconfigured'}
function originalRecordLink(record){const href=originalURL(record);return href&&!href.startsWith('#')?`<a href="${esc(href)}" target="_blank" rel="noopener">Original record ↗</a>`:'<span class="small">Original file reader is not connected.</span>'}
function referenceOverview(p){const records=(p.records||[p.record]).filter(Boolean);return `<section class="referenceOverview"><h2>${esc(p.name)}</h2><p>Configured source overview. No source state or publication status is inferred.</p>${records.map(record=>`<p>${esc(record)}</p>`).join('')}</section>`}
function createLocalProject(){const name=document.getElementById('new-project-name').value.trim()||'Untitled project',id=uid(),p={id,name,step:'Writing',status:'Writing · local study',view:'article',subtitle:'Your local writing project.',folder:'Ideas',archived:false,blocks:[{id:uid(),tag:'p',html:'<br>',source:'Author writing · local study',quote:false}],rev:1,history:[],scroll:0,note:null,slides:[]};rememberPosition();state.projects.push(p);state.project=id;state.projectFilter='all';selected=null;activeBlock=null;keyboardBlock=null;modal=null;save();render();document.getElementById('manuscript')?.focus();toast('New project created in this browser only. Start writing directly.')}
function saveFiling(){const p=current();p.folder=document.getElementById('file-folder').value.trim()||'Projects';p.archived=document.getElementById('file-archive').checked;state.projectFilter=p.archived?'archive':p.folder;modal=null;save();render();toast('Browser-only filing saved. Original files and workflow stage unchanged.')}
function reorderProject(delta){const i=state.projects.findIndex(p=>p.id===state.project),j=i+delta;if(j<0||j>=state.projects.length)return;const [p]=state.projects.splice(i,1);state.projects.splice(j,0,p);save();render();toast('Local project list order changed. Original index unchanged.')}

const originalModalHTML=modalHTML;modalHTML=function(p){if(modal==='newProject')return `<div class="popoverBackdrop" onclick="if(event.target===this){modal=null;render()}"><section class="popover"><button class="close quiet" onclick="modal=null;render()">Close ×</button><h2>A new project</h2><p>Start with your own words. No recording or final editorial title required.</p><label for="new-project-name">Working name</label><input id="new-project-name" placeholder="Untitled project" onkeydown="if(event.key==='Enter')createLocalProject()"><div class="actions"><button class="primary" onclick="createLocalProject()">Start writing</button></div><p class="small">Local browser project only; no folder or file is created.</p></section></div>`;if(modal==='filing')return `<div class="popoverBackdrop" onclick="if(event.target===this){modal=null;render()}"><section class="popover"><button class="close quiet" onclick="modal=null;render()">Close ×</button><h2>File ${esc(p.name)}</h2><p>This organizes the browser list only. It does not move a story’s existing files or change its current workflow step.</p><label for="file-folder">Folder label</label><input id="file-folder" value="${esc(p.folder||'Projects')}" placeholder="Projects"><label class="archiveCheck"><input type="checkbox" id="file-archive" ${p.archived?'checked':''}> Archive in this local list</label><div class="actions"><button class="primary" onclick="saveFiling()">Save filing</button><button onclick="reorderProject(-1)">Move project up</button><button onclick="reorderProject(1)">Move project down</button></div><p class="small">Choose Archive in the list to restore a project; uncheck this same archive control. Browser filing never changes source files or workflow records.</p></section></div>`;if(modal==='carouselSource')return `<div class="popoverBackdrop" onclick="if(event.target===this){modal=null;render()}"><section class="popover"><button class="close quiet" onclick="modal=null;render()">Close ×</button><h2>Configured carousel words</h2><p>No source receipt or approval is inferred from this display.</p><div class="context" style="white-space:pre-wrap;max-height:350px">${esc(HK_LINEUP.changes)}</div><p>These are the supplied local word lines. Prototype template choices do not assert a look approval, matched photo or production export.</p></section></div>`;return originalModalHTML(p)};
initializeBrowser();initializeWorkflow();applyTheme();render();
